import{z as n,x as A,o as E,c as B,q as r,j as d,D as i,d as a,s,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"idle 线程","description":"","frontmatter":{"title":"idle 线程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/idle-thread.md","filePath":"cs/idle-thread.md","lastUpdated":1791063341000}'),p={name:"cs/idle-thread.md"};function C(m,e,c,h,u,D){const t=A("Mermaid");return E(),B("div",null,[e[2]||(e[2]=r('<h1 id="idle-线程" tabindex="-1">idle 线程 <a class="header-anchor" href="#idle-线程" aria-label="Permalink to &quot;idle 线程&quot;">​</a></h1><div class="epigraph"><p>每颗 CPU 始终要有一条可运行的任务：没有用户工作时，就跑 idle——停机等待中断，而不是在空队列上空转调度器。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/fpu-lazy">上一课</a>降低了切换时的寄存器搬运。调度器仍要回答：就绪集合为空时把程序计数器指到哪。若「没有任务」就让 CPU 执行垃圾，机器会飞。<a href="/cs/percpu">per-CPU 数据</a> 已有核本地状态。缺口是每 CPU 一条 <strong>idle 线程</strong>：永远可运行、优先级最低，体内停机或低功耗等待，被中断叫醒后再进入调度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时钟与设备 IRQ 必须有一个执行上下文来跑上半部；若 CPU 真的「什么都没有」，连中断返回后要恢复的 PCB 都不存在。idle 提供这个底：它是内核线程，无用户地址空间，调度类里排在所有真正工作之后。缺口不是 FPU 策略，而是<strong>空转的合法形态</strong>。</p><p><span class="marginnote">直觉类比：idle 像夜班保安——楼里没人（就绪队列空）时他不能消失，只能找角落打盹（停机等中断）；门铃一响立刻起身开门（先跑中断处理），再决定要不要叫醒别人。「永远可运行」保证任何时刻都有人当值。</span></p><p><span class="marginnote">idle 里调用 <code>wait_for_interrupt</code> 一类指令，打开中断并停核。唤醒后先跑 ISR，再看是否有新就绪任务；没有则再次停。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动时为每个 CPU 创建 idle <code>task_struct</code>，永不退出。主调度循环：选最高优先级就绪任务；若无，选 idle。idle 不累计用户时间。负载统计常把 idle 时间单独记账，以免把「核在睡觉」当成「核在跑公平份额」。</p><p><span class="marginnote">数字实例：一秒内某核跑用户任务 300 ms、内核 100 ms、idle 600 ms，利用率就是 (1000−600)/1000 = 40%。注意「100% 忙」不等于「100% 有用」——若那 400 ms 全耗在自旋锁空转，统计上一派繁忙，实际什么都没推进；idle 单独记账正是为了戳破这种假忙。</span></p>',10)),(E(),d(o,null,{default:i(()=>[s(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%B0%B1%E7%BB%AA%E9%98%9F%E5%88%97%E7%A9%BA%3F%22%5D%20--%3E%20I%5B%22%E8%B7%91%20idle%3A%20%E5%81%9C%E6%9C%BA%E7%AD%89%E4%B8%AD%E6%96%AD%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E8%B7%91%E6%99%AE%E9%80%9A%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20I%20--%3E%20IRQ%5B%22%E4%B8%AD%E6%96%AD%E5%94%A4%E9%86%92%22%5D%0A%20%20IRQ%20--%3E%20Q%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=l("p",null,"禁止在 idle 里做重活；否则等于偷了一个永远可运行的低优先级工人，延迟难以解释。",-1)),e[4]||(e[4]=l("h2",{id:"机制",tabindex:"-1"},[a("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=l("p",null,[a("idle 让「CPU 利用率」有定义：非 idle 时间 / 墙钟。与"),l("a",{href:"/cs/interrupt-bottom-half"},"中断下半部"),a("会合：设备完成把线程唤醒，idle 被抢占。与内核抢占：idle 自己可被立即切走，因为它不持用户锁。功耗：深 C-state 进 idle 再进，退出延迟是实时课的 WCET 来源之一，本课只承认停机有代价。")],-1)),(E(),d(o,null,{default:i(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDLE%5B%22%E8%BF%9B%E5%85%A5%20idle%22%5D%20--%3E%20C0%5B%22%E6%B5%85%E5%81%9C%E6%9C%BA%EF%BC%9A%E9%80%80%E5%87%BA%E5%8F%AA%E8%A6%81%E5%87%A0%E7%BA%B3%E7%A7%92%22%5D%0A%20%20IDLE%20--%3E%20C2%5B%22%E6%B7%B1%E5%81%9C%E6%9C%BA%EF%BC%9A%E5%85%B3%E7%BC%93%E5%AD%98%EF%BC%8C%E9%80%80%E5%87%BA%E5%BE%AE%E7%A7%92%E7%BA%A7%22%5D%0A%20%20IDLE%20--%3E%20C6%5B%22%E6%9C%80%E6%B7%B1%EF%BC%9A%E5%85%B3%E6%A0%B8%EF%BC%8C%E6%81%A2%E5%A4%8D%E5%85%A8%E9%83%A8%E7%8A%B6%E6%80%81%E6%9B%B4%E4%B9%85%22%5D%0A%20%20C0%20--%3E%20W%5B%22%E5%94%A4%E9%86%92%EF%BC%9A%E5%85%88%E8%B7%91%E4%B8%AD%E6%96%AD%E5%86%8D%E8%B0%83%E5%BA%A6%22%5D%0A%20%20C2%20--%3E%20W%0A%20%20C6%20--%3E%20W%0A%20%20W%20--%3E%20D%5B%22%E9%80%80%E5%87%BA%E5%BB%B6%E8%BF%9F%E8%AE%A1%E5%85%A5%E5%AE%9E%E6%97%B6%E4%BB%BB%E5%8A%A1%E7%9A%84%20WCET%22%5D%0A"})]),fallback:i(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=r('<p><span class="marginnote">常见误区：以为 CPU 空闲就「不花钱」。深停机省电，但唤醒要把缓存、流水线状态一点点恢复；中断又密又急时，核在「睡—醒」之间反复折腾，反而更耗电、延迟更差。Governor 得先预测这次能睡多久再决定睡多深，猜错两头吃亏。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 cpuidle 治理器的全部策略写成电源管理课。也不把「空循环 busy idle」当现代默认。tickless 内核如何关掉空闲核上的时钟中断，点到即可。</p><p>后课默认：CPU 上永远有当前任务，可能是 idle。有多条真工作时如何比较好坏，下一课先定义<a href="/cs/scheduling-metrics">调度指标</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每 CPU 一条 idle：队列空则停机等中断。</li><li>利用率相对 idle 来定义；idle 不做重活。</li><li>尺子（周转、响应、公平）是下一课。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',6))])}const P=n(p,[["render",C]]);export{_ as __pageData,P as default};
